package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class TwoDigitShortDivisionTest {
 private Question make(int n,int d){return ShortWrittenDivision.indexedTwoDigit(ShortWrittenDivision.SHORT_TWO,(n-1)*90+d-10);}
 private int[] repeat(int n,int d){int q=0;while(n>=d){n-=d;q++;}return new int[]{q,n};}
 @Test public void everyDivisorWithSelectedBoundariesUsesShortWorkspaceAndPublicChecking(){for(int d=10;d<=99;d++)for(int n:new int[]{1,d-1,d,d+1,100,101,999,1000,1001,4001,9999}){Question q=make(n,d);q.answers=new String[]{"poison","poison"};q.expression="poison";int[] expected=repeat(n,d);Checker c=new Checker();assertTrue(c.check(q,List.of(),List.of(""+expected[0],""+expected[1])).correct());assertEquals(1,c.check(q,List.of(),List.of(""+expected[0],""+(expected[1]+1))).index);VerticalWork.Layout l=VerticalWork.layout(q);assertNotNull(l);assertTrue(l.rows.stream().noneMatch(r->r.id.startsWith("product")));assertEquals(Integer.toString(n).length()+1,l.rows.size());HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertEquals(2+3*Integer.toString(n).length(),h.size());assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));int rest=0,step=2;for(char ch:Integer.toString(n).toCharArray()){int current=rest*10+ch-'0';int[] local=repeat(current,d);assertTrue(h.step(step++).accepts(""+current));assertTrue(h.step(step++).accepts(""+local[0]));rest=local[1];assertTrue(h.step(step++).accepts(""+rest));}}}
 @Test public void internalZerosAndTwoDigitRemainderStayStudentEntries(){Question q=make(4013,40);VerticalWork.Draft draft=new VerticalWork.Draft();assertNull(VerticalWork.answers(q,draft));draft.cells.put("answer:2","1");draft.cells.put("answer:1","0");draft.cells.put("answer:0","0");draft.cells.put("rest0:1","1");assertNull(VerticalWork.answers(q,draft));draft.cells.put("rest0:0","4");assertEquals(Set.of("rest0:0"),VerticalWork.check(q,draft).wrong);draft.cells.put("rest0:0","3");assertFalse(VerticalWork.check(q,draft).error());assertEquals(List.of("100","13"),VerticalWork.answers(q,draft));Question longQ=ShortWrittenDivision.indexedLong((4013-1)*90+40-10);assertTrue(VerticalWork.layout(longQ).rows.stream().anyMatch(r->r.id.startsWith("product")));}
 @Test public void freshYearSixPlacementRetainsOldShortAndLongDomains(){Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"GB");GlobalCurriculum.choosePack(p,"england-primary-2021-v1");for(int grade=1;grade<=6;grade++)assertEquals(grade==6,GlobalCurriculum.pack(p).inGrade(ShortWrittenDivision.SHORT_TWO,grade));assertFalse(Curriculum.inCurriculum(Catalog.get(ShortWrittenDivision.SHORT_TWO),2022));Generator g=new Generator(new Random(194));List<String> recent=new ArrayList<>();CurriculumLimits limits=GlobalCurriculum.limits(p.educationSystem,ShortWrittenDivision.SHORT_TWO,6);for(int i=0;i<150;i++){Question q=g.next(ShortWrittenDivision.SHORT_TWO,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());assertNotNull(ShortWrittenDivision.read(q));assertTrue(limits.allows(q));assertTrue(q.choices.isEmpty());}for(String prompt:List.of("0 ÷ 10","10000 ÷ 10","12 ÷ 9","12 ÷ 100")){Question q=make(12,10);q.prompt=prompt;assertNull(ShortWrittenDivision.read(q));assertNull(VerticalWork.layout(q));}}
}
